function madridOffsetMs(t) {
    // Offset de España peninsular con cambio de hora automático
    // (último domingo de marzo 01:00 UTC -> último domingo de octubre 01:00 UTC)
    function lastSundayUtc1(y, m) {
        var last = new Date(Date.UTC(y, m + 1, 0));
        return Date.UTC(y, m, last.getUTCDate() - last.getUTCDay(), 1, 0, 0);
    }
    var y = new Date(t).getUTCFullYear();
    return (t >= lastSundayUtc1(y, 2) && t < lastSundayUtc1(y, 9)) ? 7200000 : 3600000;
}

function fechaLocal(t) {
    var off = madridOffsetMs(t);
    var d = new Date(t + off);
    return {
        fecha: d.getUTCFullYear() + "-" + ("0" + (d.getUTCMonth() + 1)).slice(-2) + "-" + ("0" + d.getUTCDate()).slice(-2),
        anio: "" + d.getUTCFullYear()
    };
}

// ===== Decodificar trama + acumulados batcheados (v4 - SIN retraso de confirmacion) =====
var MAX_CAUDAL = 999999999999;       // l/s: limite maximo permitido por caudalimetro
var MAX_DT_S = 3600;                 // tope de integracion tras un corte de comunicaciones (segundos)

function parseObj(value) {
    if (!value) { return {}; }
    if (typeof value === "string") {
        try { return JSON.parse(value); } catch (e) { return {}; }
    }
    if (typeof value === "object") { return value; }
    return {};
}

function r3(x) { return Math.round(x * 1000) / 1000; }

function buildBaseMetadata(source, tsOverride) {
    var target = {};
    target.ts = (tsOverride !== undefined && tsOverride !== null) ? String(tsOverride) : source.ts;
    if (source.deviceType) { target.deviceType = source.deviceType; }
    if (source.deviceName) { target.pila_origen = source.deviceName; }
    if (source.Pila_de_Datos) { target.Pila_de_Datos = source.Pila_de_Datos; }
    return target;
}

var data = msg.data;
if (!data || typeof data !== "string") {
    throw new Error("Mensaje sin campo 'data'");
}

var grupo = parseObj(msg.ss_grupo_v4 || metadata.ss_grupo_v4);
var maxPorNombre = parseObj(msg.ss_caudal_maximo_v1 || metadata.ss_caudal_maximo_v1);
// >>> NUEVO v2.5: signos +Suma/-Resta sincronizados desde el widget (Bloque A).
// Se leen aqui, UNA vez por trama, para poder calcular el total YA firmado del
// grupo en el mismo bucle que decodifica todos los caudalimetros -- sin repartir
// el calculo en varios mensajes independientes (eso causaba los saltos raros en
// los volumenes: dos caudalimetros del mismo grupo actualizando el mismo mapa
// compartido casi a la vez, pisandose el uno al otro).
var signos = parseObj(msg.ss_operaciones_caudalimetros_v1 || metadata.ss_operaciones_caudalimetros_v1);
var nPos = 0;
for (var kk in grupo) { if (grupo.hasOwnProperty(kk)) { nPos++; } }
if (nPos === 0) {
    throw new Error("Atributo grupo_v4 ausente o vacio en la pila");
}

var caudalesHex = data.slice(12, -14);
var totalVals = Math.floor(caudalesHex.length / 4);
if (totalVals !== nPos) {
    throw new Error("La trama trae " + totalVals + " caudalimetros y grupo_v4 define " + nPos);
}

// ---- Estado de acumulacion: UN solo atributo por pila (acumulados_v2) ----
var st = parseObj(msg.ss_acumulados_v2 || metadata.ss_acumulados_v2);
var ts = metadata.ts ? parseInt(metadata.ts) : new Date().getTime();

var tsAnterior = (st._lastTs !== undefined) ? parseInt(st._lastTs) : undefined;
var dtSeg = 0;
if (tsAnterior !== undefined) {
    dtSeg = (ts - tsAnterior) / 1000;
    if (dtSeg < 0) { dtSeg = 0; }
    if (dtSeg > MAX_DT_S) { dtSeg = MAX_DT_S; }
}

var fl = fechaLocal(ts);
var fechaActual = fl.fecha;
var anioActual = fl.anio;

var items = [];
var sumaPorGrupo = {};
var diarioPorGrupo = {};
// >>> NUEVO v2.5: acumuladores YA firmados (con +1/-1 segun el widget), uno por
// grupo. Calculados en el MISMO bucle que decodifica la trama -> sin carreras.
var sumaFirmadaPorGrupo = {};
var diarioFirmadoPorGrupo = {};
var anualFirmadoPorGrupo = {};
var totalFirmadoPorGrupo = {};

for (var i = 0; i < caudalesHex.length; i += 4) {
    var posicion = i / 4;
    var hex = caudalesHex.slice(i, i + 4);
    if (hex.length < 4) { continue; }
    var decimalNuevo = parseInt(hex, 16); // lectura RAW de esta trama
    var info = grupo[String(posicion)];
    if (!info) { continue; }

    var nombre = info.n;
    var grupoRiego = info.g;
    var e = st[nombre];
    if (!e) { e = {}; }

    var caudal = decimalNuevo;
    var caudalRaw = null;
    var caudalLimitado = false;
    var limiteItem = (maxPorNombre[nombre] !== undefined && maxPorNombre[nombre] !== null && maxPorNombre[nombre] !== "" && !isNaN(parseFloat(maxPorNombre[nombre])))
        ? parseFloat(maxPorNombre[nombre])
        : null;
    if (limiteItem !== null && caudal > limiteItem) {
        caudalRaw = caudal;
        caudal = limiteItem;
        caudalLimitado = true;
    }

    var cierreDia = null;
    var cierreAnio = null;
    var anualPrevio = (e.a !== undefined) ? e.a : 0;
    if (e.f !== fechaActual) {
        if (e.f !== undefined) { cierreDia = (e.d !== undefined) ? e.d : 0; }
        e.d = 0;
        e.f = fechaActual;
    }
    if (e.aR !== anioActual) {
        if (e.aR !== undefined) { cierreAnio = anualPrevio; }
        e.a = 0;
        e.aR = anioActual;
    }

    var vol = caudal * dtSeg / 1000;
    e.d = (e.d !== undefined ? e.d : 0) + vol;
    e.a = (e.a !== undefined ? e.a : 0) + vol;
    if (e.t === undefined) { e.t = anualPrevio; }
    e.t = e.t + vol;
    e.lc = caudal;
    e.d = r3(e.d); e.a = r3(e.a); e.t = r3(e.t);
    st[nombre] = e;

    var item = {
        deviceName: nombre,
        grupo_riego: grupoRiego,
        caudal: caudal,
        state: caudal > 0,
        volumen_intervalo_m3: r3(vol),
        caudal_total_diario_m3: e.d,
        caudal_total_anual_m3: e.a,
        caudal_total_m3: e.t
    };
    if (caudalRaw !== null) { item.caudal_raw = caudalRaw; }
    if (caudalLimitado) { item.caudal_limitado = true; }
    if (cierreDia !== null) { item.caudal_total_dia_cerrado = r3(cierreDia); }
    if (cierreAnio !== null) { item["caudal_total_año_cerrado"] = r3(cierreAnio); }
    if (info.s !== undefined) { item.sector = info.s; }
    if (info.z !== undefined && info.z !== null) { item.zona = info.z; }
    items.push(item);

    sumaPorGrupo[grupoRiego] = (sumaPorGrupo[grupoRiego] || 0) + caudal;
    diarioPorGrupo[grupoRiego] = (diarioPorGrupo[grupoRiego] || 0) + e.d;

    // >>> NUEVO v2.5: mismo caudalimetro, pero ya con su signo aplicado.
    // Por defecto "suma" si todavia no tiene signo configurado (igual que en v2.4).
    var signo = (signos[nombre] === "resta") ? -1 : 1;
    sumaFirmadaPorGrupo[grupoRiego] = (sumaFirmadaPorGrupo[grupoRiego] || 0) + signo * caudal;
    diarioFirmadoPorGrupo[grupoRiego] = (diarioFirmadoPorGrupo[grupoRiego] || 0) + signo * e.d;
    anualFirmadoPorGrupo[grupoRiego] = (anualFirmadoPorGrupo[grupoRiego] || 0) + signo * e.a;
    totalFirmadoPorGrupo[grupoRiego] = (totalFirmadoPorGrupo[grupoRiego] || 0) + signo * e.t;
}

var RESTAR_DE_OTRO_GRUPO = {
    "La Española": "La Española Desembalse"
};

for (var gAjuste in RESTAR_DE_OTRO_GRUPO) {
    if (!RESTAR_DE_OTRO_GRUPO.hasOwnProperty(gAjuste)) { continue; }
    var gRestar = RESTAR_DE_OTRO_GRUPO[gAjuste];
    if (sumaPorGrupo[gRestar] === undefined) { continue; }

    items.push({
        deviceName: gAjuste,
        grupo_riego: gAjuste,
        ajuste_resta_otro_grupo: sumaPorGrupo[gRestar],
        ajuste_resta_otro_grupo_diario_m3: r3(diarioPorGrupo[gRestar] || 0),
        tipo: "grupo"
    });
}

// >>> NUEVO v2.5: un item de "totales ya firmados" por cada Grupo_Riego presente
// en esta trama -- sustituye el calculo repartido en varios mensajes (nodos
// "Cargar mapa/signos.." a "Guardar caudal_operaciones (GR)" viejos).
for (var gTotal in sumaFirmadaPorGrupo) {
    if (!sumaFirmadaPorGrupo.hasOwnProperty(gTotal)) { continue; }
    items.push({
        deviceName: gTotal,
        grupo_riego: gTotal,
        tipo: "operaciones_totales",
        caudal_Sum_v2: r3(sumaFirmadaPorGrupo[gTotal]),
        caudal_total_diario_m3_v2: r3(diarioFirmadoPorGrupo[gTotal] || 0),
        caudal_total_anual_m3_v2: r3(anualFirmadoPorGrupo[gTotal] || 0),
        caudal_total_m3_v2: r3(totalFirmadoPorGrupo[gTotal] || 0)
    });
}

st._lastTs = ts;
delete st._pendienteRaw;
delete st._lastDtSeg;

var target = buildBaseMetadata(metadata, ts);
target.acumulados_out = JSON.stringify(st);
target.manuales_activos_hoy = metadata.ss_manuales_activos_hoy || "{}";

return { msg: items, metadata: target, msgType: msgType };

var msg2 = {
    caudal_fijado: msg.caudal_medio_diario
};

// ts de inicio del día que trae el nodo de agregación
var startTs = metadata.ts ? parseInt(metadata.ts) : new Date().getTime();
var endOfDayTs = startTs + 86399000; // 23:59:59.000 del mismo día

// metadata para el punto de las 00:00 (la de siempre, sin tocar)
var metadataInicio = metadata;

// metadata para el punto de las 23:59:59 (copia independiente con el ts cambiado)
var metadataFin = JSON.parse(JSON.stringify(metadata));
metadataFin.ts = String(endOfDayTs);

return [
    { msg: msg2, metadata: metadataInicio, msgType: msgType },
    { msg: msg2, metadata: metadataFin, msgType: msgType }
];

// ============================================================
// Nodo: "Procesar Ciclo (tz Madrid)"  --  Cadena: Pila_de_Datos_v2.3
// (aparece dos veces en la cadena: una para el grupo de riego / caudalimetro,
// otra para el sector -- este arreglo aplica igual a las dos copias, el
// script es idéntico en ambas)
//
// FIX 1 (2026-09-18): media_proyectada daba la MITAD de lo que debía.
// Causa: "Calcular caudal fijado (incremental)" dispara el "save" en
// CADA trama con un mensaje vacío (sin caudal_Sum/caudal_Sum_v2) para
// mantener vivo el flujo, y este script lo contaba como caudal = 0.
// Arreglo: "tieneCaudalReal" -- si no trae caudal_Sum/_v2, no se acumula.
// CONFIRMADO EN PRODUCCION (18/09/2026): El Rosario paso de ~15 a 31,
// igual que el caudal real.
//
// FIX 2 (2026-09-18): cada trama real se contaba DOS veces (el filtro
// "tipo" deja pasar tanto tipo:"grupo" como tipo:"operaciones_totales" de
// la MISMA trama, y las dos disparan este nodo con el mismo caudal_Sum_v2).
//
// FIX 2, v3: la primera version de este fix (v2) detectaba el duplicado
// comparando caudal_total_diario_m3_v2 entre tramas -- pero eso falla
// si el grupo esta parado (caudal = 0): dos tramas reales SEGUIDAS con
// caudal 0 tienen el mismo total acumulado (no sube), y se confundirian
// con un duplicado, perdiendo una lectura real de 0 (la media saldria
// mas alta de lo real en los grupos que paran durante el dia).
//
// Arreglo v3: en vez de comparar el total, se mide el TIEMPO transcurrido
// desde la ultima trama real ya contada. Los dos duplicados de una misma
// trama (grupo + operaciones_totales) llegan con milisegundos de
// diferencia; dos tramas reales de verdad siempre estan separadas ~15
// minutos. Si el tiempo transcurrido es menor que UMBRAL_DUPLICADO_MS,
// es el duplicado de la misma trama -- no se cuenta otra vez.
// ============================================================

var UMBRAL_DUPLICADO_MS = 10000; // 10 segundos

function madridOffsetMs(t) {
    function lastSundayUtc1(y, m) {
        var last = new Date(Date.UTC(y, m + 1, 0));
        return Date.UTC(y, m, last.getUTCDate() - last.getUTCDay(), 1, 0, 0);
    }
    var y = new Date(t).getUTCFullYear();
    return (t >= lastSundayUtc1(y, 2) && t < lastSundayUtc1(y, 9)) ? 7200000 : 3600000;
}

// 1. Dato real entrante
var tieneCaudalReal = (msg.caudal_Sum_v2 !== undefined && msg.caudal_Sum_v2 !== null) ||
                      (msg.caudal_Sum !== undefined && msg.caudal_Sum !== null);

var caudal = 0;
if (tieneCaudalReal) {
    caudal = (msg.caudal_Sum_v2 !== undefined && msg.caudal_Sum_v2 !== null)
        ? parseFloat(msg.caudal_Sum_v2)
        : parseFloat(msg.caudal_Sum);
    if (isNaN(caudal)) {
        caudal = 0;
        tieneCaudalReal = false;
    }
}

// 2. Calcular la hora real y el inicio del día
var ts = metadata.ts ? parseInt(metadata.ts) : new Date().getTime();
var offsetEspana = madridOffsetMs(ts);
var d = new Date(ts + offsetEspana);
d.setUTCHours(0, 0, 0, 0);
var inicio_dia_ts = d.getTime() - offsetEspana;
var dia_actual = new Date(inicio_dia_ts).getDate();

// 3. Rescatar memoria (con el historial de 4 y el ts de la última trama contada)
var mem_dia = (metadata.ss_dia !== undefined) ? parseInt(metadata.ss_dia) : -1;
var suma = (metadata.ss_suma !== undefined) ? parseFloat(metadata.ss_suma) : 0;
var contador = (metadata.ss_contador !== undefined) ? parseInt(metadata.ss_contador) : 0;
var last_4_str = (metadata.ss_last_4 !== undefined) ? metadata.ss_last_4 : "";
var ultimo_ts_contado = (metadata.ss_ultimo_ts_contado !== undefined && metadata.ss_ultimo_ts_contado !== "")
    ? parseInt(metadata.ss_ultimo_ts_contado) : null;

// 4. Reset a cero si cambiamos de día
if (dia_actual !== mem_dia) {
    suma = 0;
    contador = 0;
    last_4_str = "";
    ultimo_ts_contado = null;
}

// 5. FIX 2 (v3): duplicado de la misma trama si llega a menos de
// UMBRAL_DUPLICADO_MS de la ultima trama real ya contada.
var esDuplicado = tieneCaudalReal && ultimo_ts_contado !== null &&
    Math.abs(ts - ultimo_ts_contado) < UMBRAL_DUPLICADO_MS;

// 6. Solo acumulamos si trae caudal real Y no es un duplicado de la misma trama
if (tieneCaudalReal && !esDuplicado) {
    suma += caudal;
    contador += 1;

    var last_4_arr = last_4_str ? last_4_str.split(',').map(Number) : [];
    last_4_arr.push(caudal);
    if (last_4_arr.length > 4) {
        last_4_arr.shift();
    }
    last_4_str = last_4_arr.join(',');

    ultimo_ts_contado = ts;
}

// 7. Preparar paquete para el simulador del futuro (Script 2)
metadata.caudal_val = caudal.toString();
metadata.suma_val = suma.toString();
metadata.contador_val = contador.toString();
metadata.inicio_dia_ts = inicio_dia_ts.toString();
metadata.ts_real = ts.toString();
metadata.last_4_val = last_4_str;

// 8. Guardar variables de estado en el amarillo
var msg_attr = {
    dia: dia_actual,
    suma: suma,
    contador: contador,
    last_4: last_4_str,
    ultimo_ts_contado: (ultimo_ts_contado !== null ? ultimo_ts_contado : "")
};

return {msg: msg_attr, metadata: metadata, msgType: "POST_ATTRIBUTES_REQUEST"};

var caudal_ultimo = parseFloat(metadata.caudal_val);
var suma_actual = parseFloat(metadata.suma_val);
var contador_actual = parseInt(metadata.contador_val);
var inicio_dia = parseInt(metadata.inicio_dia_ts);
var ts_real = parseInt(metadata.ts_real);

// --- TENDENCIA DE LOS ÚLTIMOS 4 ---
var last_4_str = metadata.last_4_val || caudal_ultimo.toString();
var last_4_arr = last_4_str.split(',').map(Number);
var suma_tendencia = 0;
for (var j = 0; j < last_4_arr.length; j++) {
    suma_tendencia += last_4_arr[j];
}
var caudal_tendencia = suma_tendencia / last_4_arr.length;

var MS_15_MIN = 900000;
var MS_DIA = 86400000; // 24h

// Fin del día = último segundo del día actual (23:59:59.999),
// para que el punto se vea dentro del mismo día y no se pierda
// al caer en el bucket del día siguiente.
var fin_dia = inicio_dia + MS_DIA - 1;

// Cuántos slots de 15 min quedan hasta el final del día
var slot_actual = Math.floor((ts_real - inicio_dia) / MS_15_MIN);
var pasos_restantes = 96 - (slot_actual + 1);
if (pasos_restantes < 0) pasos_restantes = 0;

// Proyección acumulada: sumamos la tendencia por cada slot que falta
var suma_simulada = suma_actual + (caudal_tendencia * pasos_restantes);
var contador_simulado = contador_actual + pasos_restantes;
var media_final = Math.round((suma_simulada / contador_simulado) * 100) / 100;

// Solo 2 puntos, mismo valor -> línea recta horizontal visible en el día actual
var proyectados = [
    {
        "ts": inicio_dia,
        "values": { "media_proyectada": media_final }
    },
    {
        "ts": fin_dia,
        "values": { "media_proyectada": media_final }
    }
];

return {msg: proyectados, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

// ============================================================
// Nodo: "calcular_resumen (s/z)"  --  Cadena: Pila_de_Datos_v2.3
//
// FIX (2026-09-17): caudal_s0 (y en general cualquier caudal_sX) se estaba
// pisando con SOLO el valor manual cada vez que llegaba una trama de
// CUALQUIER Pila del sistema, aunque esa Pila no tuviera nada que ver con
// ese sector.
//
// Causa: "manualSumsGlobal" se calcula a partir del atributo
// "manuales_activos_hoy", que es GLOBAL (todos los manuales activos de
// TODO el sistema, no solo los de los grupos que trae ESTA trama). Como
// consecuencia, el bucle que decide que sectores hay que emitir
// ("sectoresAEmitir") metia un sector con manual activo AUNQUE la trama
// actual no trajera ni un solo grupo de ese sector -- y al no haber datos
// automaticos de ese sector en "sums", el resultado emitido era solo el
// manual (p.ej. caudal_s0 = 0 + 50 = 50), borrando el ultimo total
// correcto (automatico + manual) que habia dejado la Pila que si es de
// ese sector.
//
// Confirmado con debug: una trama de Sector 3/4 (sin ningun grupo de
// sector 0) emitia igualmente "caudal_s0": 50, pisando el 106 real.
//
// Arreglo: un sector solo puede emitirse/pisarse si esta REALMENTE
// cubierto por la trama actual (es decir, si al menos un grupo de esa
// Pila pertenece a ese sector) -- "sectoresCubiertos", calculado a partir
// de "grupoSectorSiempre" (que ya se rellena para TODOS los grupos de la
// trama, tengan o no manual activo). Asi, una Pila de otro sector nunca
// puede tocar el total de un sector que no le pertenece, y el sector
