// propia Pila reporta.
// ============================================================

function parseObj(v) {
    if (!v) { return {}; }
    if (typeof v === "string") { try { return JSON.parse(v); } catch (e) { return {}; } }
    if (typeof v === "object") { return v; }
    return {};
}
function normKey(s) {
    if (s === undefined || s === null) { return ""; }
    var desde = "áéíóúÁÉÍÓÚüÜñÑàèìòùÀÈÌÒÙâêîôûÂÊÎÔÛäëïöÄËÏÖ";
    var hasta = "aeiouAEIOUuUnNaeiouAEIOUaeiouAEIOUaeioAEIO";
    var out = "";
    var str = String(s);
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        var idx = desde.indexOf(ch);
        out += (idx !== -1) ? hasta.charAt(idx) : ch;
    }
    return out
        .trim()
