var items = msg;
if (!Array.isArray(items)) {
    return { msg: msg, metadata: metadata, msgType: msgType };
}

var manuales = parseObj(metadata.manuales_activos_hoy);
var tsActual = new Date().getTime();
var diaActual = fechaLocal(tsActual);

var manualesNorm = {};
for (var gk in manuales) {
    if (manuales.hasOwnProperty(gk)) { manualesNorm[normKey(gk)] = manuales[gk]; }
}

var sums = {};
var zonas = {};

var debugExcluidos = [];
var debugNoExcluidos = [];

var sumaPorGrupoReal = {};
var grupoSector = {};
var sumaPorGrupoSiempre = {};
var grupoSectorSiempre = {};

for (var i = 0; i < items.length; i++) {
    var it = items[i];
    if (it.tipo === "grupo") { continue; }

    var caud = parseFloat(it.caudal) || 0;
    var grupo = it.grupo_riego;

    if (it.sector !== undefined) {
        var manual = manualesNorm[normKey(grupo)];
        var manualActivo = (manual !== undefined && manual.dia === diaActual);

        sumaPorGrupoSiempre[grupo] = (sumaPorGrupoSiempre[grupo] || 0) + caud;
        grupoSectorSiempre[grupo] = it.sector;

        if (!manualActivo) {
            sumaPorGrupoReal[grupo] = (sumaPorGrupoReal[grupo] || 0) + caud;
            grupoSector[grupo] = it.sector;
        } else {
            if (debugExcluidos.indexOf(grupo) === -1) { debugExcluidos.push(grupo); }
        }
    }
    if (it.zona) {
        zonas[it.zona] = (zonas[it.zona] || 0) + caud;
    }
